import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        TaskC solver = new TaskC();
        solver.solve(1, br, pw);
        pw.close();
    }

    static class TaskC {
        final double eps = 1e-8;

        public void solve(int testNumber, BufferedReader br, PrintWriter out) throws IOException {
            int n = Integer.parseInt(br.readLine());
            Circle[] circles = new Circle[n];
            for (int i = 0; i < n; i++) {
                String[] parts = br.readLine().split(" ");
                int x = Integer.parseInt(parts[0]);
                int y = Integer.parseInt(parts[1]);
                int r = Integer.parseInt(parts[2]);
                circles[i] = new Circle(new Point(x, y), r);
            }

            Set<Point> allPoints = new TreeSet<>();
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    List<Point> inters = intersect(circles[i], circles[j]);
                    if (inters != null) {
                        allPoints.addAll(inters);
                    }
                }
            }

            Map<Point, Integer> pointIdMap = new TreeMap<>();
            List<Set<Integer>> adjacency = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                List<Double> angles = new ArrayList<>();
                final int K = 100;
                for (int j = 0; j < K; j++) {
                    angles.add(Math.PI * 2 * j / K);
                }
                for (Point p : allPoints) {
                    if (circles[i].contains(p)) {
                        double dx = p.x - circles[i].o.x;
                        double dy = p.y - circles[i].o.y;
                        double alpha = Math.atan2(dy, dx);
                        if (alpha < 0) alpha += 2 * Math.PI;
                        angles.add(alpha);
                    }
                }
                Collections.sort(angles);
                Point dir = new Point(1,0).scale(circles[i].r);
                Double[] as = new TreeSet<>(angles).toArray(new Double[0]);
                for (Double a : as) {
                    Point p = circles[i].o.add(dir.rotate(a));
                    getId(p, pointIdMap, adjacency);
                }
                for (int j = 0; j < as.length; j++) {
                    Point p1 = circles[i].o.add(dir.rotate(as[j]));
                    Point p2 = circles[i].o.add(dir.rotate(as[(j + 1) % as.length]));
                    int u = pointIdMap.get(p1);
                    int v = pointIdMap.get(p2);
                    if (u != v) {
                        adjacency.get(u).add(v);
                        adjacency.get(v).add(u);
                    }
                }
            }

            int vertices = adjacency.size();
            int edges = 0;
            for (Set<Integer> neighbors : adjacency) {
                edges += neighbors.size();
            }
            edges /= 2;

            int components = 0;
            boolean[] visited = new boolean[vertices];
            for (int i = 0; i < vertices; i++) {
                if (!visited[i]) {
                    components++;
                    dfs(i, visited, adjacency);
                }
            }

            out.println(1 + components + edges - vertices);
        }

        private void dfs(int u, boolean[] visited, List<Set<Integer>> adj) {
            visited[u] = true;
            for (int v : adj.get(u)) {
                if (!visited[v]) {
                    dfs(v, visited, adj);
                }
            }
        }

        private void getId(Point p, Map<Point, Integer> pointId, List<Set<Integer>> adj) {
            if (!pointId.containsKey(p)) {
                int id = pointId.size();
                pointId.put(p, id);
                adj.add(new TreeSet<>());
            }
        }

        private List<Point> intersect(Circle c1, Circle c2) {
            double dx = c1.o.x - c2.o.x;
            double dy = c1.o.y - c2.o.y;
            double d = Math.hypot(dx, dy);
            double cos = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d);
            if (cos < -1 - eps || cos > 1 + eps) return null;
            if (cos < -1) cos = -1;
            if (cos > 1) cos = 1;
            double alpha = Math.acos(cos);
            Point dir = c2.o.sub(c1.o).norm();
            List<Point> res = new ArrayList<>();
            res.add(c1.o.add(dir.scale(c1.r).rotate(+alpha)));
            res.add(c1.o.add(dir.scale(c1.r).rotate(-alpha)));
            return res;
        }

        class Point implements Comparable<Point> {
            double x, y;

            Point(double x, double y) {
                this.x = x;
                this.y = y;
            }

            Point add(Point o) {
                return new Point(x + o.x, y + o.y);
            }

            Point sub(Point o) {
                return new Point(x - o.x, y - o.y);
            }

            Point rotate(double alpha) {
                double c = Math.cos(alpha);
                double s = Math.sin(alpha);
                return new Point(x * c - y * s, x * s + y * c);
            }

            Point norm() {
                double len = length();
                if (len < eps) return new Point(0,0);
                return scale(1.0 / len);
            }

            Point scale(double f) {
                return new Point(x * f, y * f);
            }

            double length() {
                return Math.hypot(x, y);
            }

            public String toString() {
                return String.format("%.6f %.6f", x, y);
            }

            public boolean equals(Object o) {
                if (!(o instanceof Point)) return false;
                Point p = (Point) o;
                return Math.abs(x - p.x) < eps && Math.abs(y - p.y) < eps;
            }

            public int compareTo(Point o) {
                if (Math.abs(x - o.x) > eps) return Double.compare(x, o.x);
                return Double.compare(y, o.y);
            }
        }

        class Circle {
            Point o;
            double r;

            Circle(Point o, double r) {
                this.o = o;
                this.r = r;
            }

            boolean contains(Point p) {
                return Math.abs(p.sub(o).length() - r) < eps;
            }
        }
    }
}
