import math
import sys

def main():
    input = sys.stdin.read
    data = input().splitlines()
    n = int(data[0])
    circles = []
    for i in range(n):
        x, y, r = map(int, data[i+1].split())
        circles.append(Circle(Point(x, y), r))
    all_points = set()
    for i in range(n):
        for j in range(i+1, n):
            inters = intersect(circles[i], circles[j])
            if inters is not None:
                all_points.update(inters)
    point_id_map = {}
    adjacency = []
    def get_id(p):
        if p not in point_id_map:
            point_id_map[p] = len(adjacency)
            adjacency.append(set())
        return point_id_map[p]
    for i in range(n):
        angles = []
        K = 100
        for j in range(K):
            angles.append(2 * math.pi * j / K)
        for p in all_points:
            if circles[i].contains(p):
                dx = p.x - circles[i].o.x
                dy = p.y - circles[i].o.y
                alpha = math.atan2(dy, dx)
                if alpha < 0:
                    alpha += 2 * math.pi
                angles.append(alpha)
        angles = sorted(set(angles))
        dir_vector = Point(1, 0).scale(circles[i].r)
        as_list = sorted(set(angles))
        for a in as_list:
            p = circles[i].o.add(dir_vector.rotate(a))
            get_id(p)
        for j in range(len(as_list)):
            p1 = circles[i].o.add(dir_vector.rotate(as_list[j]))
            p2 = circles[i].o.add(dir_vector.rotate(as_list[(j + 1) % len(as_list)]))
            u = get_id(p1)
            v = get_id(p2)
            if u != v:
                adjacency[u].add(v)
                adjacency[v].add(u)
    vertices = len(adjacency)
    edges = sum(len(neigh) for neigh in adjacency) // 2
    visited = [False] * vertices
    def dfs(u):
        visited[u] = True
        for v in adjacency[u]:
            if not visited[v]:
                dfs(v)
    components = 0
    for i in range(vertices):
        if not visited[i]:
            components += 1
            dfs(i)
    print(1 + components + edges - vertices)

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def add(self, o):
        return Point(self.x + o.x, self.y + o.y)
    def sub(self, o):
        return Point(self.x - o.x, self.y - o.y)
    def rotate(self, alpha):
        c = math.cos(alpha)
        s = math.sin(alpha)
        return Point(self.x * c - self.y * s, self.x * s + self.y * c)
    def norm(self):
        length = self.length()
        if length < 1e-8:
            return Point(0, 0)
        return self.scale(1.0 / length)
    def scale(self, f):
        return Point(self.x * f, self.y * f)
    def length(self):
        return math.hypot(self.x, self.y)
    def __str__(self):
        return f"{self.x:.6f} {self.y:.6f}"
    def __eq__(self, other):
        if not isinstance(other, Point):
            return False
        return abs(self.x - other.x) < 1e-8 and abs(self.y - other.y) < 1e-8
    def __hash__(self):
        return hash((round(self.x, 8), round(self.y, 8)))
    def __lt__(self, other):
        if abs(self.x - other.x) > 1e-8:
            return self.x < other.x
        return self.y < other.y

class Circle:
    def __init__(self, o, r):
        self.o = o
        self.r = r
    def contains(self, p):
        return abs(p.sub(self.o).length() - self.r) < 1e-8

def intersect(c1, c2):
    dx = c1.o.x - c2.o.x
    dy = c1.o.y - c2.o.y
    d = math.hypot(dx, dy)
    cos_value = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d) if d != 0 else 1
    if cos_value < -1 - 1e-8 or cos_value > 1 + 1e-8:
        return None
    if cos_value < -1:
        cos_value = -1
    if cos_value > 1:
        cos_value = 1
    alpha = math.acos(cos_value)
    dir_vector = c2.o.sub(c1.o).norm()
    res = []
    res.append(c1.o.add(dir_vector.scale(c1.r).rotate(+alpha)))
    res.append(c1.o.add(dir_vector.scale(c1.r).rotate(-alpha)))
    return res

